import {money,esc,empty} from './ui.js';
export function renderTrend(series){
 const values=series.flatMap(p=>[p.actual,p.expected]).filter(v=>Number.isFinite(v));if(!values.length)return empty('暂无可比趋势','缺少实际数据或预期基线时，不绘制利润曲线。');
 const W=800,H=245,L=64,R=25,T=18,B=35;const low=Math.min(0,...values),high=Math.max(1,...values);const span=(high-low)*1.13;const y=v=>T+(high*1.08-v)/span*(H-T-B);const x=i=>L+i*(W-L-R)/Math.max(1,series.length-1);
 let grid='';for(let i=0;i<5;i++){const v=low+(high-low)*i/4;grid+=`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#edf1f6"/><text x="${L-12}" y="${y(v)+4}" text-anchor="end">${Math.abs(v)>=10000?(v/10000).toFixed(1)+'万':Math.round(v).toLocaleString()}</text>`;}
 const path=key=>{let pen=false;return series.map((p,i)=>{if(p[key]===null){pen=false;return '';}const s=`${pen?'L':'M'}${x(i)},${y(p[key])}`;pen=true;return s;}).join(' ');};
 const labels=series.map((p,i)=>i%Math.max(1,Math.ceil(series.length/8))===0||i===series.length-1?`<text x="${x(i)}" y="${H-8}" text-anchor="middle">${p.date.slice(5).replace('-','/')}</text>`:'').join('');
 const dots=series.map((p,i)=>p.actual===null?'':`<g class="chart-point" tabindex="0" role="button" data-day="${p.date}" aria-label="${p.date} 实际 ${money(p.actual)}，预期 ${money(p.expected)}"><title>${p.date} · 实际 ${money(p.actual)} · 预期 ${money(p.expected)}${p.missing?' · '+p.missing+' 笔无当日日报':''}</title><circle cx="${x(i)}" cy="${y(p.actual)}" r="11" fill="transparent"/><circle cx="${x(i)}" cy="${y(p.actual)}" r="3.3" fill="#3274ef" stroke="white" stroke-width="1.5"/></g>`).join('');
 return `<svg class="trend-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="实际与同期预期生产毛利趋势；点击数据点查看日期">${grid}<path d="${path('expected')}" fill="none" stroke="#a6b3c7" stroke-width="2" stroke-dasharray="5 5"/><path d="${path('actual')}" fill="none" stroke="#3274ef" stroke-width="3" stroke-linejoin="round"/>${dots}${labels}</svg>`;
}
export function renderCostVariance(items){const max=Math.max(1,...items.map(i=>Math.abs(i.delta??0)));return `<div class="variance-bars">${items.map(i=>`<div class="variance-row"><span>${esc(i.name)}</span><div class="bar-track"><div class="bar-fill ${i.delta>0?'red':'green'}" style="width:${Math.abs(i.delta??0)/max*100}%"></div></div><strong class="${i.delta>0?'negative':'positive'}">${i.delta===null?'—':(i.delta>0?'+':'−')+money(Math.abs(i.delta))}</strong></div>`).join('')}</div>`;}
